BY_SLUG = {f["slug"]: f for f in FOODS}


def get_food(slug):
    """One food by slug, or None."""
    return BY_SLUG.get((slug or "").strip().lower())


def foods_in(category=None):
    """Every food, or just one category, sorted by English name."""
    rows = FOODS if not category else [f for f in FOODS if f["cat"] == category]
    return sorted(rows, key=lambda f: f["en"].lower())


def category_name(key, lang="ar"):
    pair = CATEGORIES.get(key)
    if not pair:
        return key
    return pair[0] if lang == "ar" else pair[1]
